  Ciphertext w = x * alpha;
  Ciphertext u = w * w;
  Ciphertext t2 = u + u - one;
  Ciphertext s = t2 * t2;
  Ciphertext s2 = s + s;
  Ciphertext A = s2 + s2 - one - one - one;
  Ciphertext B = A * c6;
  Ciphertext C = t2 * c4;
  Ciphertext inner = B + C + C;
  inner = inner + c2;
